  const eq = (a, b) => JSON.stringify(a) === JSON.stringify(b);
  return [
    { pass: eq(fn("hello", "hello"), ["green","green","green","green","green"]), description: 'Exact match returns all green', got: JSON.stringify(fn("hello", "hello")) },
    { pass: eq(fn("abcde", "fghij"), ["gray","gray","gray","gray","gray"]), description: 'No matching letters returns all gray', got: JSON.stringify(fn("abcde", "fghij")) },
    { pass: eq(fn("crane", "react"), ["yellow","yellow","green","gray","yellow"]), description: 'Scrambled letters — a is green (correct position), c/r/e are yellow', got: JSON.stringify(fn("crane", "react")) },
    { pass: eq(fn("apple", "plead"), ["yellow","yellow","gray","yellow","yellow"]), description: 'Handles duplicate letters — second p has no match left', got: JSON.stringify(fn("apple", "plead")) },
    { pass: eq(fn("speed", "abcde"), ["gray","gray","yellow","gray","yellow"]), description: 'Two e letters — first e is yellow, d is yellow', got: JSON.stringify(fn("speed", "abcde")) },
    { pass: eq(fn("aabbb", "aaccc"), ["green","green","gray","gray","gray"]), description: 'Matching prefix with non-matching suffix', got: JSON.stringify(fn("aabbb", "aaccc")) },
    { pass: eq(fn("xxxxx", "xaaaa"), ["green","gray","gray","gray","gray"]), description: 'Repeated guess letter — only one green, rest gray', got: JSON.stringify(fn("xxxxx", "xaaaa")) }
  ];
}

exercises.solution:
function slideAndMerge(row) {
  // Remove zeros
  let nums = row.filter(n => n !== 0);
  let score = 0;
  // Merge adjacent equal values
  const merged = [];
  let i = 0;
  while (i < nums.length) {
    if (i + 1 < nums.length && nums[i] === nums[i + 1]) {
      merged.push(nums[i] * 2);
      score += nums[i] * 2;
      i += 2;
    } else {
      merged.push(nums[i]);
      i++;
    }
  }
  // Pad with zeros
  while (merged.length < 4) {
    merged.push(0);
  }
  return { row: merged, score };
}

