exercises.solution:
function createTicTacToe() {
  let board = [[null,null,null],[null,null,null],[null,null,null]];
  let currentPlayer = "X";
  let gameOver = false;
  let gameWinner = null;

  function checkWinner() {
    for (let r = 0; r < 3; r++) {
      if (board[r][0] && board[r][0] === board[r][1] && board[r][1] === board[r][2]) return board[r][0];
    }
    for (let c = 0; c < 3; c++) {
      if (board[0][c] && board[0][c] === board[1][c] && board[1][c] === board[2][c]) return board[0][c];
    }
    if (board[0][0] && board[0][0] === board[1][1] && board[1][1] === board[2][2]) return board[0][0];
    if (board[0][2] && board[0][2] === board[1][1] && board[1][1] === board[2][0]) return board[0][2];
    return null;
  }

  function isFull() {
    return board.every(row => row.every(cell => cell !== null));
  }

  return {
    makeMove(row, col) {
      if (gameOver || row < 0 || row > 2 || col < 0 || col > 2 || board[row][col] !== null) {
        return { valid: false, winner: null, draw: false };
      }
      board[row][col] = currentPlayer;
      const w = checkWinner();
      if (w) {
        gameOver = true;
        gameWinner = w;
        return { valid: true, winner: w, draw: false };
      }
      if (isFull()) {
        gameOver = true;
        return { valid: true, winner: null, draw: true };
      }
      currentPlayer = currentPlayer === "X" ? "O" : "X";
      return { valid: true, winner: null, draw: false };
    },
    getBoard() {
      return board.map(row => [...row]);
    },
    getCurrentPlayer() {
      return currentPlayer;
    },
    reset() {
      board = [[null,null,null],[null,null,null],[null,null,null]];
      currentPlayer = "X";
      gameOver = false;
      gameWinner = null;
    }
  };
}

exercises.testRunner:
(code) => {
  const createFn = new Function(code + '; return createTicTacToe;')();
  const eq = (a, b) => JSON.stringify(a) === JSON.stringify(b);

  // Test 1: Initial board is empty
  const g1 = createFn();
  const emptyBoard = [[null,null,null],[null,null,null],[null,null,null]];
  const t1 = eq(g1.getBoard(), emptyBoard);

  // Test 2: First player is X
  const g2 = createFn();
  const t2 = g2.getCurrentPlayer() === "X";

  // Test 3: Valid move places X and returns valid:true
  const g3 = createFn();
  const r3 = g3.makeMove(0, 0);
  const t3 = r3.valid === true && g3.getBoard()[0][0] === "X";

  // Test 4: After X moves, current player is O
  const g4 = createFn();
  g4.makeMove(0, 0);
  const t4 = g4.getCurrentPlayer() === "O";

  // Test 5: Invalid move on occupied cell returns valid:false
  const g5 = createFn();
  g5.makeMove(1, 1);
  const r5 = g5.makeMove(1, 1);
  const t5 = r5.valid === false;

  // Test 6: X wins with top row
  const g6 = createFn();
  g6.makeMove(0, 0); // X
  g6.makeMove(1, 0); // O
  g6.makeMove(0, 1); // X
  g6.makeMove(1, 1); // O
  const r6 = g6.makeMove(0, 2); // X wins top row
  const t6 = r6.valid === true && r6.winner === "X";

  // Test 7: O wins with column
  const g7 = createFn();
  g7.makeMove(0, 0); // X
  g7.makeMove(0, 2); // O
  g7.makeMove(1, 0); // X
  g7.makeMove(1, 2); // O
  g7.makeMove(2, 1); // X
  const r7 = g7.makeMove(2, 2); // O wins right column
  const t7 = r7.valid === true && r7.winner === "O";

  // Test 8: Draw detection
  const g8 = createFn();
  g8.makeMove(0, 0); // X
  g8.makeMove(0, 1); // O
  g8.makeMove(0, 2); // X
  g8.makeMove(1, 0); // O
  g8.makeMove(1, 1); // X
  g8.makeMove(2, 0); // O
  g8.makeMove(1, 2); // X
  g8.makeMove(2, 2); // O
  const r8 = g8.makeMove(2, 1); // X — board full, no winner
  const t8 = r8.valid === true && r8.winner === null && r8.draw === true;

  // Test 9: Cannot move after game is over
  const g9 = createFn();
  g9.makeMove(0, 0); g9.makeMove(1, 0);
  g9.makeMove(0, 1); g9.makeMove(1, 1);
  g9.makeMove(0, 2); // X wins
  const r9 = g9.makeMove(2, 2);
  const t9 = r9.valid === false;

  // Test 10: Reset clears board and sets player to X
  const g10 = createFn();
  g10.makeMove(0, 0);
  g10.makeMove(1, 1);
  g10.reset();
  const t10 = eq(g10.getBoard(), emptyBoard) && g10.getCurrentPlayer() === "X";

  return [
