exercises.solution:
function createHangman(word, maxLives) {
  word = word.toLowerCase();
  maxLives = maxLives || 6;
  let livesRemaining = maxLives;
  let guessedLetters = new Set();
  let gameOver = false;
  let won = false;

  function allRevealed() {
    return word.split('').every(ch => guessedLetters.has(ch));
  }

  return {
    guess(letter) {
      if (gameOver || typeof letter !== 'string' || letter.length !== 1 || !/[a-zA-Z]/.test(letter)) {
        return { valid: false, correct: false, alreadyGuessed: false, gameOver: false, won: false };
      }
      letter = letter.toLowerCase();
      if (guessedLetters.has(letter)) {
        return { valid: true, correct: false, alreadyGuessed: true, gameOver: false, won: false };
      }
      guessedLetters.add(letter);
      const correct = word.includes(letter);
      if (!correct) {
        livesRemaining--;
      }
      if (allRevealed()) {
        gameOver = true;
        won = true;
      } else if (livesRemaining <= 0) {
        gameOver = true;
        won = false;
      }
      return { valid: true, correct, alreadyGuessed: false, gameOver, won };
    },
    getDisplay() {
      return word.split('').map(ch => guessedLetters.has(ch) ? ch : '_').join('');
    },
    getState() {
      return {
        guessedLetters: Array.from(guessedLetters).sort(),
        livesRemaining,
        gameOver,
        won
      };
    }
  };
}

