exercises.solution:
function createMemoryGame(pairs, shuffled) {
  let board;
  if (shuffled) {
    board = shuffled.map(value => ({ value, flipped: false, matched: false }));
  } else {
    const doubled = [...pairs, ...pairs];
    for (let i = doubled.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [doubled[i], doubled[j]] = [doubled[j], doubled[i]];
    }
    board = doubled.map(value => ({ value, flipped: false, matched: false }));
  }

  let firstFlipIndex = null;
  let secondFlipIndex = null;
  let matches = 0;
  let attempts = 0;

  function resetPreviousTurn() {
    if (firstFlipIndex !== null && secondFlipIndex !== null) {
      if (!board[firstFlipIndex].matched) {
        board[firstFlipIndex].flipped = false;
      }
      if (!board[secondFlipIndex].matched) {
        board[secondFlipIndex].flipped = false;
      }
      firstFlipIndex = null;
      secondFlipIndex = null;
    }
  }

  return {
    flip(index) {
      if (index < 0 || index >= board.length || board[index].matched) {
        return { valid: false, value: null, matched: false, turnComplete: false };
      }

      // If a completed turn is pending, reset those cards first
      if (firstFlipIndex !== null && secondFlipIndex !== null) {
        resetPreviousTurn();
      }

      if (board[index].flipped) {
        return { valid: false, value: null, matched: false, turnComplete: false };
      }

      board[index].flipped = true;

      if (firstFlipIndex === null) {
        // First flip of a turn
        firstFlipIndex = index;
        return { valid: true, value: board[index].value, matched: false, turnComplete: false };
      } else {
        // Second flip of a turn
        secondFlipIndex = index;
        attempts++;
        const isMatch = board[firstFlipIndex].value === board[secondFlipIndex].value;
        if (isMatch) {
          board[firstFlipIndex].matched = true;
          board[secondFlipIndex].matched = true;
          matches++;
          firstFlipIndex = null;
          secondFlipIndex = null;
        }
        return { valid: true, value: board[index].value, matched: isMatch, turnComplete: true };
      }
    },
    getBoard() {
      return board.map(card => ({
        flipped: card.flipped,
        matched: card.matched,
        value: (card.flipped || card.matched) ? card.value : null
      }));
    },
    getScore() {
      return { matches, attempts };
    },
    isComplete() {
      return matches === pairs.length;
    }
  };
}

