function createSnake(width, height) {
  const startRow = Math.floor(height / 2);
  const startCol = Math.floor(width / 2);
  let snake = [{ row: startRow, col: startCol }];
  let food = null;
  let score = 0;
  let gameOver = false;

  const directions = {
    up: { row: -1, col: 0 },
    down: { row: 1, col: 0 },
    left: { row: 0, col: -1 },
    right: { row: 0, col: 1 }
  };

  return {
    move(direction) {
      if (gameOver || !directions[direction]) {
        return { valid: false, ate: false, gameOver, score };
      }

      const head = snake[0];
      const delta = directions[direction];
      const newHead = { row: head.row + delta.row, col: head.col + delta.col };

      // Wall collision
      if (newHead.row < 0 || newHead.row >= height || newHead.col < 0 || newHead.col >= width) {
        gameOver = true;
        return { valid: true, ate: false, gameOver: true, score };
      }

      // Self collision (check before removing tail since we haven't moved yet)
      const hitsBody = snake.some(seg => seg.row === newHead.row && seg.col === newHead.col);
      if (hitsBody) {
        gameOver = true;
        return { valid: true, ate: false, gameOver: true, score };
      }

      // Check food
      const ate = food !== null && newHead.row === food.row && newHead.col === food.col;

      // Add new head
      snake.unshift(newHead);

      if (ate) {
        score++;
        food = null;
        // Don't remove tail — snake grows
      } else {
        // Remove tail
        snake.pop();
      }

      return { valid: true, ate, gameOver: false, score };
    },
    getState() {
      return {
        snake: snake.map(s => ({ row: s.row, col: s.col })),
        food: food ? { row: food.row, col: food.col } : null,
        score,
        gameOver
      };
    },
    placeFood(row, col) {
      food = { row, col };
    }
  };
}

