exercises.solution:
function createWordle(targetWord) {
  const target = targetWord.toLowerCase();
  const history = [];
  let gameOver = false;
  let won = false;
  const maxGuesses = 6;

  function scoreGuess(guess) {
    const result = Array.from({ length: 5 }, (_, i) => ({ letter: guess[i], status: "gray" }));
    const targetLetters = target.split("");
    const used = Array(5).fill(false);

    // First pass: greens
    for (let i = 0; i < 5; i++) {
      if (guess[i] === target[i]) {
        result[i].status = "green";
        used[i] = true;
      }
    }

    // Second pass: yellows
    for (let i = 0; i < 5; i++) {
      if (result[i].status === "green") continue;
      for (let j = 0; j < 5; j++) {
        if (!used[j] && guess[i] === targetLetters[j]) {
          result[i].status = "yellow";
          used[j] = true;
          break;
        }
      }
    }

    return result;
  }

  function guess(word) {
    const w = word.toLowerCase();
    if (w.length !== 5 || gameOver || history.length >= maxGuesses) {
      return { valid: false, result: [], gameOver, won };
    }

    const result = scoreGuess(w);
    history.push(result);

    if (result.every(r => r.status === "green")) {
      gameOver = true;
      won = true;
    } else if (history.length >= maxGuesses) {
      gameOver = true;
    }

    return { valid: true, result, gameOver, won };
  }

  function getHistory() {
    return history.map(entry => entry.map(r => ({ ...r })));
  }

  function getState() {
    return { guessesRemaining: maxGuesses - history.length, gameOver, won };
  }

  return { guess, getHistory, getState };
}

