  // Test 3: Wrong guess returns mix of green/yellow/gray
  const g3 = createWordle("crane");
  const r3 = g3.guess("react");
  const statuses3 = r3.result.map(r => r.status);
  const hasGreen = statuses3.includes("green");
  const hasYellow = statuses3.includes("yellow");
  const hasGray = statuses3.includes("gray");
  results.push({ pass: !!r3.valid && hasGreen && hasYellow && hasGray, description: 'Wrong guess returns mix of green/yellow/gray', got: JSON.stringify(statuses3) });

  // Test 4: Invalid guess (not 5 letters) returns valid:false
  const g4 = createWordle("crane");
  const r4a = g4.guess("hi");
  const r4b = g4.guess("toolong");
  results.push({ pass: r4a.valid === false && r4b.valid === false, description: 'Invalid guess (not 5 letters) returns valid:false', got: JSON.stringify({ short: r4a.valid, long: r4b.valid }) });

  // Test 5: History records all guesses
  const g5 = createWordle("crane");
  g5.guess("hello");
  g5.guess("world");
  const h5 = g5.getHistory();
  results.push({ pass: h5.length === 2 && h5[0].length === 5 && h5[1].length === 5, description: 'History records all guesses', got: 'history length: ' + h5.length });

  // Test 6: Guesses remaining decrements
  const g6 = createWordle("crane");
  g6.guess("hello");
  g6.guess("world");
  const s6 = g6.getState();
  results.push({ pass: s6.guessesRemaining === 4, description: 'Guesses remaining decrements after each guess', got: String(s6.guessesRemaining) });

  // Test 7: Game over after 6 wrong guesses
  const g7 = createWordle("crane");
  const words7 = ["hello", "world", "fuzzy", "jumps", "quick", "blitz"];
  words7.forEach(w => g7.guess(w));
  const s7 = g7.getState();
  results.push({ pass: s7.gameOver === true && s7.guessesRemaining === 0, description: 'Game over after 6 wrong guesses', got: JSON.stringify(s7) });

  // Test 8: Cannot guess after game over
  const g8 = createWordle("crane");
  g8.guess("crane");
  const r8 = g8.guess("hello");
  results.push({ pass: r8.valid === false, description: 'Cannot guess after game over', got: 'valid: ' + r8.valid });

  // Test 9: Duplicate letters handled correctly (green priority)
  const g9 = createWordle("abbey");
  const r9 = g9.guess("babby");
  const s9 = r9.result.map(r => r.status);
  // target: a-b-b-e-y, guess: b-a-b-b-y
  // pos0: b vs a -> not green. pos1: a vs b -> not green. pos2: b vs b -> green. pos3: b vs e -> not green. pos4: y vs y -> green
  // yellows: pos0 b -> match at pos1 (unused) -> yellow. pos1 a -> match at pos0 (unused) -> yellow. pos3 b -> no unused b left -> gray
  results.push({ pass: s9[2] === "green" && s9[4] === "green" && s9[0] === "yellow" && s9[1] === "yellow" && s9[3] === "gray", description: 'Duplicate letters handled correctly (green priority)', got: JSON.stringify(s9) });

  // Test 10: Won is false when out of guesses
  const g10 = createWordle("crane");
  const words10 = ["hello", "world", "fuzzy", "jumps", "quick", "blitz"];
  words10.forEach(w => g10.guess(w));
  const s10 = g10.getState();
  results.push({ pass: s10.won === false && s10.gameOver === true, description: 'Won is false when out of guesses without correct answer', got: JSON.stringify({ won: s10.won, gameOver: s10.gameOver }) });

  return results;
}

exercises.instructions:
Write a function `createBlackjack(deckCards)` where `deckCards` is a pre-shuffled array of card objects (each with `rank` and `value` properties) to use as the deck. Returns a game object with four methods:

**`deal()`** — Deal 2 cards to the player and 2 to the dealer, alternating (player, dealer, player, dealer) from the top of the deck. Returns the initial game state.

**`hit()`** — Deal one more card to the player from the top of the deck. Returns updated state. If the player's score exceeds 21, the game is over and the dealer wins.

**`stand()`** — The dealer draws cards from the deck until reaching a score of 17 or higher. Then compare scores to determine the winner. Returns the final state.

**`getState()`** — Returns:
```
{
  playerHand: [{ rank, value }, ...],
  dealerHand: [{ rank, value }, ...],
  playerScore: number,
  dealerScore: number,
  gameOver: boolean,
  result: null | "player_win" | "dealer_win" | "push"
}
```

**Ace handling:** Aces count as 11 unless that would cause the hand to exceed 21, in which case they count as 1. Multiple aces adjust independently.

**Result is `null` during active play**, then one of `"player_win"`, `"dealer_win"`, or `"push"` when the game ends.

Example:
```
const deck = [
  { rank: "K", value: 10 }, { rank: "9", value: 9 },
  { rank: "7", value: 7 }, { rank: "8", value: 8 }, ...
];
const game = createBlackjack(deck);
game.deal();
// Player: K, 7 (17)  Dealer: 9, 8 (17)
game.stand();
// Dealer stays at 17. Push.
```

exercises.solution:
function createBlackjack(deckCards) {
  const deck = [...deckCards];
  let deckIndex = 0;
  const playerHand = [];
  const dealerHand = [];
  let gameOver = false;
  let result = null;

  function drawCard() {
    return deck[deckIndex++];
  }

  function scoreHand(hand) {
    let total = 0;
    let aces = 0;
    for (const card of hand) {
      total += card.value;
      if (card.value === 11) aces++;
    }
    while (total > 21 && aces > 0) {
      total -= 10;
      aces--;
    }
    return total;
  }

  function getState() {
    return {
      playerHand: playerHand.map(c => ({ rank: c.rank, value: c.value })),
      dealerHand: dealerHand.map(c => ({ rank: c.rank, value: c.value })),
      playerScore: scoreHand(playerHand),
      dealerScore: scoreHand(dealerHand),
      gameOver,
      result
    };
  }

  function deal() {
    playerHand.push(drawCard());
    dealerHand.push(drawCard());
    playerHand.push(drawCard());
    dealerHand.push(drawCard());
    return getState();
  }

  function hit() {
    if (gameOver) return getState();
    playerHand.push(drawCard());
    if (scoreHand(playerHand) > 21) {
      gameOver = true;
      result = "dealer_win";
    }
    return getState();
  }

  function stand() {
    if (gameOver) return getState();
    while (scoreHand(dealerHand) < 17) {
      dealerHand.push(drawCard());
    }
    const pScore = scoreHand(playerHand);
    const dScore = scoreHand(dealerHand);
    gameOver = true;
    if (dScore > 21 || pScore > dScore) {
      result = "player_win";
    } else if (dScore > pScore) {
      result = "dealer_win";
    } else {
      result = "push";
    }
    return getState();
  }

  return { deal, hit, stand, getState };
}

