  // Deck: [8, 5, 9, 6, 7]. Deal: player=8,9(17), dealer=5,6(11). Stand: dealer draws 7 -> 18.
  const deck6 = [card("8",8), card("5",5), card("9",9), card("6",6), card("7",7)];
  const g6 = createBlackjack(deck6);
  g6.deal();
  const s6 = g6.stand();
  results.push({ pass: s6.dealerScore >= 17 && s6.dealerHand.length >= 3, description: 'Stand triggers dealer to draw until 17+', got: 'dealerScore: ' + s6.dealerScore + ', dealerCards: ' + s6.dealerHand.length });

  // Test 7: Player wins with higher score (both under 21)
  // Deck: [K, 3, 9, 4, J]. Deal: player=K,9(19), dealer=3,4(7). Stand: dealer draws J -> 17. Player 19 > 17.
  const deck7 = [card("K",10), card("3",3), card("9",9), card("4",4), card("J",10)];
  const g7 = createBlackjack(deck7);
  g7.deal();
  const s7 = g7.stand();
  results.push({ pass: s7.result === "player_win" && s7.gameOver === true, description: 'Player wins with higher score (both under 21)', got: JSON.stringify({ result: s7.result, pScore: s7.playerScore, dScore: s7.dealerScore }) });

  // Test 8: Dealer wins with higher score
  const deck8 = [card("5",5), card("K",10), card("3",3), card("9",9), card("J",10)];
  const g8 = createBlackjack(deck8);
  g8.deal();
  // Player: 5+3=8, Dealer: K(10)+9(9)=19. Player stands at 8. Dealer already at 19.
  const s8 = g8.stand();
  results.push({ pass: s8.result === "dealer_win" && s8.gameOver === true, description: 'Dealer wins with higher score', got: JSON.stringify({ result: s8.result, pScore: s8.playerScore, dScore: s8.dealerScore }) });

  // Test 9: Push when scores are equal
  const deck9 = [card("K",10), card("Q",10), card("7",7), card("7",7)];
  const g9 = createBlackjack(deck9);
  g9.deal();
  // Player: K(10)+7(7)=17, Dealer: Q(10)+7(7)=17
  const s9 = g9.stand();
  results.push({ pass: s9.result === "push" && s9.gameOver === true, description: 'Push when scores are equal', got: JSON.stringify({ result: s9.result, pScore: s9.playerScore, dScore: s9.dealerScore }) });

  // Test 10: Cannot hit or stand after game over
  const deck10 = [card("K",10), card("Q",10), card("7",7), card("7",7), card("2",2)];
  const g10 = createBlackjack(deck10);
  g10.deal();
  g10.stand();
  const s10h = g10.hit();
  const s10s = g10.stand();
  results.push({ pass: s10h.playerHand.length === 2 && s10s.dealerHand.length === 2, description: 'Cannot hit or stand after game over (hands unchanged)', got: 'playerCards: ' + s10h.playerHand.length + ', dealerCards: ' + s10s.dealerHand.length });

  return results;
}

exercises.solution:
function createConnectFour() {
  const ROWS = 6;
  const COLS = 7;
  let board;
  let currentPlayer;
  let winner;
  let moveCount;

  function init() {
    board = Array.from({ length: ROWS }, () => Array(COLS).fill(null));
    currentPlayer = "R";
    winner = null;
    moveCount = 0;
  }

  init();

  function checkDirection(row, col, dr, dc) {
    const piece = board[row][col];
    if (!piece) return false;
    for (let i = 1; i < 4; i++) {
      const r = row + dr * i;
      const c = col + dc * i;
      if (r < 0 || r >= ROWS || c < 0 || c >= COLS || board[r][c] !== piece) {
        return false;
      }
    }
    return true;
  }

  function checkWinner(row, col) {
    const directions = [
      [0, 1],   // horizontal
      [1, 0],   // vertical
      [1, 1],   // diagonal down-right
      [1, -1]   // diagonal down-left
    ];
    for (const [dr, dc] of directions) {
      for (let start = 0; start < 4; start++) {
        const startRow = row - dr * start;
        const startCol = col - dc * start;
        if (startRow >= 0 && startRow < ROWS && startCol >= 0 && startCol < COLS) {
          if (checkDirection(startRow, startCol, dr, dc)) {
            return board[row][col];
          }
        }
      }
    }
    return null;
  }

  function dropPiece(col) {
    if (col < 0 || col > 6 || winner) {
      return { valid: false, row: null, winner, draw: false };
    }

    // Find lowest empty row
    let targetRow = -1;
    for (let r = ROWS - 1; r >= 0; r--) {
      if (board[r][col] === null) {
        targetRow = r;
        break;
      }
    }

    if (targetRow === -1) {
      return { valid: false, row: null, winner, draw: false };
    }

    board[targetRow][col] = currentPlayer;
    moveCount++;

    winner = checkWinner(targetRow, col);
    const draw = !winner && moveCount === ROWS * COLS;

    const result = { valid: true, row: targetRow, winner, draw };

    if (!winner && !draw) {
      currentPlayer = currentPlayer === "R" ? "Y" : "R";
    }

    return result;
  }

  function getBoard() {
    return board.map(row => [...row]);
  }

  function getCurrentPlayer() {
    return currentPlayer;
  }

  function reset() {
    init();
  }

  return { dropPiece, getBoard, getCurrentPlayer, reset };
}

